<?php
// FN Avanzamento Gallerie – pagina d'ingresso: primo avvio, login, logout e app
declare(strict_types=1);
require __DIR__ . '/lib.php';
boot();

// forza HTTPS quando il server lo offre (su altervista.org è disponibile)
$https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https');
// FN_FORCE_HTTPS=0 (CasaOS / Umbrel in rete locale): nessun reindirizzamento a https
$forceHttps = (getenv('FN_FORCE_HTTPS') ?: ($_SERVER['FN_FORCE_HTTPS'] ?? '1')) !== '0';
if ($forceHttps && !$https && !in_array($_SERVER['HTTP_HOST'] ?? '', ['localhost', '127.0.0.1']) && !preg_match('/^(localhost|127\.0\.0\.1)(:\d+)?$/', $_SERVER['HTTP_HOST'] ?? '')) {
    header('Location: https://' . $_SERVER['HTTP_HOST'] . $_SERVER['REQUEST_URI'], true, 301); exit;
}

$msg = ''; $err = '';
$action = $_POST['do'] ?? ($_GET['do'] ?? '');
$hasUsers = count(users()) > 0;

if ($action === 'logout') { audit('logout'); $_SESSION = []; session_destroy(); header('Location: ./'); exit; }

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($_SESSION['csrf'], (string)($_POST['csrf'] ?? ''))) { $err = 'Sessione scaduta, riprova.'; }
    elseif ($action === 'setup' && !$hasUsers) {
        $nu = trim((string)($_POST['user'] ?? '')); $pw = (string)($_POST['pass'] ?? ''); $pw2 = (string)($_POST['pass2'] ?? '');
        if (!valid_username($nu)) $err = 'Nome utente non valido (3-32 caratteri: lettere, numeri, . _ -).';
        elseif (!valid_password($pw)) $err = 'La password deve avere almeno 8 caratteri.';
        elseif ($pw !== $pw2) $err = 'Le due password non coincidono.';
        else {
            with_lock(function () use ($nu, $pw) { if (!count(users())) save_users([['user' => $nu, 'name' => trim((string)($_POST['name'] ?? '')) ?: $nu, 'role' => 'admin', 'hash' => password_hash($pw, PASSWORD_DEFAULT), 'created' => date('c')]]); });
            session_regenerate_id(true); $_SESSION['u'] = $nu; $_SESSION['t'] = time(); audit('primo avvio: creato amministratore');
            header('Location: ./'); exit;
        }
    } elseif ($action === 'login') {
        $nu = trim((string)($_POST['user'] ?? '')); $pw = (string)($_POST['pass'] ?? '');
        if (login_blocked($nu)) { $err = 'Troppi tentativi errati: riprova tra 15 minuti.'; }
        else {
            $ok = null; foreach (users() as $x) if (strtolower($x['user']) === strtolower($nu)) $ok = $x;
            if ($ok && password_verify($pw, $ok['hash'])) {
                if (password_needs_rehash($ok['hash'], PASSWORD_DEFAULT)) with_lock(function () use ($ok, $pw) { $all = users(); foreach ($all as &$x) if ($x['user'] === $ok['user']) $x['hash'] = password_hash($pw, PASSWORD_DEFAULT); unset($x); save_users($all); });
                login_ok($nu); session_regenerate_id(true); $_SESSION['u'] = $ok['user']; $_SESSION['t'] = time(); audit('login');
                header('Location: ./'); exit;
            }
            login_fail($nu); audit('login fallito per ' . $nu); usleep(400000); $err = 'Nome utente o password errati.';
        }
    }
}

$u = current_user();
if ($u) {
    // utente autenticato: consegna l'app con i dati di sessione
    $cfg = json_encode(['user' => $u['user'], 'name' => $u['name'] ?? $u['user'], 'role' => $u['role'], 'csrf' => $_SESSION['csrf'], 'api' => 'api.php'], JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP);
    header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store'); header('X-Frame-Options: SAMEORIGIN');
    if (extension_loaded('zlib') && !ini_get('zlib.output_compression')) ob_start('ob_gzhandler');
    $html = file_get_contents(__DIR__ . '/private/app.html');
    // pacchetto dati privato (solo versione GitHub/Docker): mappe, schemi e dati iniziali restano nella cartella dati del server
    $pk = DATA_DIR . '/datapack.json'; $pack = '';
    if (is_file($pk)) $pack = '<script>window.FN_PACK=' . str_replace(['</', '<!--'], ['<\\/', '<\\!--'], (string)file_get_contents($pk)) . ';</script>';
    $pos = stripos($html, '<head>');
    echo $pos === false ? $html : substr($html, 0, $pos + 6) . '<script>window.FN_SERVER=' . $cfg . ';</script>' . $pack . substr($html, $pos + 6);
    exit;
}

$setup = !$hasUsers;
header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store'); header('X-Frame-Options: DENY');
?><!doctype html>
<html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>FN Avanzamento Gallerie – accesso</title>
<style>
:root{--bg-tabbar:#141414;--bg:#1c1c1c;--fg:#ececec;--line:#3a3a3a;--border:#6a6a6a;--green:#18ed93;--yellow:#dedc12;--cyan:#3ab1ef;--err:#ff6060;--p-date:#1296be;--p-time:#0eb16c;--p-path:#bebe12;--ink:#1e1e1e;--cursor:#b4b4c0;--red:#c30607;--mono:"DejaVu Sans Mono",Consolas,"Cascadia Mono",monospace;--ui:"Segoe UI",system-ui,sans-serif}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--fg);font:14px/1.45 var(--ui)}
.wrap{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px 16px 44px}
.box{width:100%;max-width:420px;border:1px solid var(--fg);padding:16px}
.plate{background:#fff;border-radius:4px;padding:16px;display:flex;gap:14px;align-items:center;margin-bottom:18px}
.plate img{width:64px;height:64px}.plate b{display:block;color:#000;font-size:15px}.plate span{color:var(--red);font-size:12.5px}.plate small{color:#000;display:block}
h1{font:700 15px var(--mono);color:var(--green);margin:0 0 2px}.sub{font:12.5px var(--mono);color:var(--yellow);margin:0 0 16px}
label{display:block;color:var(--cyan);font-size:12.5px;margin:10px 0 3px}
input{width:100%;background:var(--bg-tabbar);border:1px solid var(--line);color:var(--fg);padding:7px 9px;font:14px var(--ui);border-radius:0}
input:focus{outline:none;border-color:var(--cursor)}
button{margin-top:16px;width:100%;height:34px;background:var(--p-path);color:var(--ink);border:1px solid var(--p-path);font:600 14px var(--ui);border-radius:4px;cursor:pointer}
button:hover{filter:brightness(1.1)}
.err{color:var(--err);font:13px var(--mono);margin-top:12px}.err::before{content:"✘ "}
.note{color:#9a9a9a;font-size:12px;margin-top:14px}
.status{position:fixed;left:0;right:0;bottom:0;height:20px;display:flex;font:12px var(--mono);border-top:1px solid var(--line);background:var(--bg)}
.seg{display:flex;align-items:center;padding:0 8px 0 10px;color:var(--ink);position:relative}.seg::after{content:"";position:absolute;right:-10px;top:0;border-left:10px solid var(--c);border-top:10px solid transparent;border-bottom:10px solid transparent;z-index:2}.seg+.seg{padding-left:18px}
.s1{--c:var(--p-date);background:var(--p-date)}.s2{--c:var(--p-time);background:var(--p-time)}.s3{--c:var(--p-path);background:var(--p-path)}
.st{padding-left:18px;display:flex;align-items:center}.cur{display:inline-block;width:8px;height:14px;background:var(--cursor);margin-left:4px}
</style></head><body>
<div class="wrap"><form class="box" method="post" autocomplete="on">
  <div class="plate"><img src="data:image/jpeg;base64," alt="VC Solutions"><div><b>FERROVIENORD</b><small>Nuovi lavori TVCC gallerie</small><span>Avanzamento lavori</span></div></div>
  <?php if ($setup): ?>
    <h1>• Primo avvio •</h1><p class="sub">(crea l'utente amministratore)</p>
    <input type="hidden" name="do" value="setup">
    <label>Nome e cognome</label><input name="name" autocomplete="name">
    <label>Nome utente</label><input name="user" required pattern="[a-zA-Z0-9._-]{3,32}" autocomplete="username">
    <label>Password (almeno 8 caratteri)</label><input name="pass" type="password" required minlength="8" autocomplete="new-password">
    <label>Ripeti la password</label><input name="pass2" type="password" required minlength="8" autocomplete="new-password">
    <button type="submit">Crea amministratore ed entra</button>
    <p class="note">Gli altri utenti si creano poi dall'app, con il pulsante 👥 Utenti.</p>
  <?php else: ?>
    <h1>• Accesso •</h1><p class="sub">(avanzamento lavori TVCC gallerie)</p>
    <input type="hidden" name="do" value="login">
    <label>Nome utente</label><input name="user" required autofocus autocomplete="username" value="<?= h((string)($_POST['user'] ?? '')) ?>">
    <label>Password</label><input name="pass" type="password" required autocomplete="current-password">
    <button type="submit">Entra</button>
  <?php endif; ?>
  <input type="hidden" name="csrf" value="<?= h($_SESSION['csrf']) ?>">
  <?php if ($err): ?><div class="err"><?= h($err) ?></div><?php endif; ?>
</form></div>
<div class="status"><div class="seg s1">📅 <?= date('d/m/Y') ?></div><div class="seg s2">🕒 <?= date('H:i') ?></div><div class="seg s3">~/FN/<?= $setup ? 'setup' : 'login' ?></div><div class="st"><?= $setup ? 'primo avvio' : 'in attesa delle credenziali' ?><span class="cur"></span></div></div>
</body></html>
